import { useEffect, useRef } from 'react'
import { gsap } from '../../utils/gsapSetup'
import { useReveal } from '../../hooks/useReveal'
import SectionHeading from '../ui/SectionHeading'
import InkDivider from '../ui/InkDivider'

const STATEMENT =
  'A katana is not manufactured. It is revealed ΓÇö folded ten thousand times, quenched in sacred water, polished until only truth remains in the steel.'

const STATS = [
  { v: '700+', k: 'σ▒ñ', l: 'Folded layers of tamahagane' },
  { v: '1,000┬░', k: 'τü½', l: 'Quench temperature ΓÇö yaki-ire' },
  { v: '70cm', k: 'Θò╖', l: 'Nagasa ΓÇö cutting edge length' },
]

export default function Philosophy() {
  const rootRef = useReveal()
  const statementRef = useRef(null)

  // Word-by-word scrub reveal + brush underline
  useEffect(() => {
    const ctx = gsap.context(() => {
      gsap.fromTo('[data-word]', { opacity: 0.12 }, {
        opacity: 1,
        ease: 'none',
        stagger: 0.09,
        scrollTrigger: {
          trigger: statementRef.current,
          start: 'top 78%',
          end: 'top 22%',
          scrub: 0.35,
        },
      })

      gsap.fromTo('[data-underline]', { strokeDashoffset: 1 }, {
        strokeDashoffset: 0,
        ease: 'none',
        scrollTrigger: {
          trigger: statementRef.current,
          start: 'top 60%',
          end: 'top 30%',
          scrub: 0.5,
        },
      })
    }, rootRef)
    return () => ctx.revert()
  }, [])

  return (
    <section id="philosophy" ref={rootRef} className="relative bg-kinari text-sumi">
      {/* Vertical kanji ΓÇö right edge */}
      <div className="v-text absolute right-6 top-28 hidden select-none font-mincho text-2xl tracking-[0.5em] text-sumi/20 md:block lg:right-12">
        Σ╕ÇµÆâσàÑΘ¡é
      </div>

      <div className="mx-auto max-w-350 px-5 pb-36 pt-32 md:px-10 md:pt-40">
        <SectionHeading no="01" kanji="σô▓σ¡ª" title="Philosophy" tone="onLight" />

        {/* Statement ΓÇö scrub reveal */}
        <p
          ref={statementRef}
          className="mt-16 max-w-5xl font-mincho text-[clamp(1.9rem,4.6vw,3.6rem)] leading-[1.25] tracking-tight md:mt-20"
        >
          {STATEMENT.split(' ').map((w, i) => {
            const key = `${w}-${i}`
            if (w === 'revealed') {
              return (
                <span key={key} className="relative mr-[0.26em] inline-block">
                  <span data-word className="inline-block">{w}</span>
                  <svg className="absolute -bottom-1.5 left-0 w-full" viewBox="0 0 200 10" preserveAspectRatio="none">
                    <path
                      data-underline d="M2 7 C 50 3 120 2 198 5"
                      fill="none" stroke="#C3272B" strokeWidth="5"
                      strokeLinecap="round" pathLength="1" strokeDasharray="1"
                    />
                  </svg>
                </span>
              )
            }
            if (w === 'truth') {
              return <span key={key} data-word className="mr-[0.26em] inline-block text-shu">{w}</span>
            }
            return <span key={key} data-word className="mr-[0.26em] inline-block">{w}</span>
          })}
        </p>

        {/* Stats ΓÇö editorial row */}
        <div className="mt-20 grid gap-10 border-t border-sumi/15 pt-10 md:grid-cols-3 md:gap-6 md:pt-12">
          {STATS.map((s, i) => (
            <div key={s.l} data-reveal data-reveal-delay={i * 0.12}>
              <div className="flex items-baseline gap-3">
                <span className="font-mincho text-5xl md:text-6xl">{s.v}</span>
                <span className="font-mincho text-lg text-shu">{s.k}</span>
              </div>
              <p className="mt-3 text-[11px] uppercase tracking-[0.22em] text-sumi/55">{s.l}</p>
            </div>
          ))}
        </div>

        {/* Ink transition teaser ΓÇö next section ki taraf */}
        <InkDivider className="mx-auto mt-28 opacity-80" width="72%" />
      </div>
    </section>
  )
}

import { useEffect, useRef } from 'react'
import { gsap } from '../../utils/gsapSetup'
import { REDUCED } from '../../utils/gsapSetup'

export default function Preloader({ onDone }) {
  const rootRef = useRef(null)
  const numRef = useRef(null)



  useEffect(() => {
  if (REDUCED) {
    if (numRef.current) numRef.current.textContent = '100'
    const t = gsap.timeline()
      .to(rootRef.current, { autoAlpha: 0, duration: 0.35, delay: 0.5 })
      .call(() => onDone?.())
      .set(rootRef.current, { display: 'none' })
    return () => t.kill()
  }
  // ...purana ctx wala code as-is yahan...
  const ctx = gsap.context(() => {
      const counter = { v: 0 }
      const tl = gsap.timeline()

      tl.from('[data-kanji]', { scale: 1.5, opacity: 0, filter: 'blur(14px)', duration: 1.1, ease: 'power2.out' }, 0.15)
        .to(counter, {
          v: 100,
          duration: 1.7,
          ease: 'power2.inOut',
          onUpdate: () => {
            if (numRef.current) numRef.current.textContent = String(Math.round(counter.v)).padStart(3, '0')
          },
        }, 0.35)
        .to('[data-line]', { scaleX: 1, duration: 1.7, ease: 'power2.inOut' }, 0.35)
        .to('[data-meta]', { opacity: 1, duration: 0.6 }, 0.9)
        // Ink exit ΓÇö poora overlay upar slide
        .to(rootRef.current, { yPercent: -100, duration: 0.9, ease: 'power4.inOut' }, '+=0.3')
        // Exit ke beech mein hi site ko handover ΓÇö overlap = premium feel
        .call(() => onDone?.(), [], '-=0.55')
        .set(rootRef.current, { display: 'none' })
    }, rootRef)
    return () => ctx.revert()
}, [])


  return (
    <div ref={rootRef} className="fixed inset-0 z-60 flex flex-col bg-sumi">
      {/* Top progress line */}
      <div data-line className="h-px w-full origin-left scale-x-0 bg-shu" />

      {/* Center kanji */}
      <div className="grid flex-1 place-items-center">
        <span data-kanji className="font-mincho text-8xl text-kinari md:text-9xl">Θï╝</span>
      </div>

      {/* Bottom row */}
      <div className="flex items-end justify-between p-6 md:p-10">
        <p data-meta className="text-[10px] uppercase tracking-[0.4em] text-kinari/40 opacity-0">
          HAGANE ΓÇö µëïµëôπüíσêÇ ┬╖ Forging Scene
        </p>
        <span ref={numRef} className="font-mincho text-6xl text-kinari/90 md:text-7xl">000</span>
      </div>
    </div>
  )
}

