import { Suspense, useEffect, useRef } from 'react'
import { Canvas, useFrame, useThree } from '@react-three/fiber'
import { Environment } from '@react-three/drei'
import * as THREE from 'three'
import { gsap, ScrollTrigger } from '../utils/gsapSetup'
import Katana from './Katana'
import Petals from './Petals'
import { katanaState, katanaAPI } from './katanaState'
import { REDUCED } from '../utils/gsapSetup'

// Hero intro ka end framing ΓÇö ab sword centered hai (baseY 46 ke saath)
const CAM_END = { x: 64, y: 16, z: 150, tx: 0, ty: 4, tz: 0 }

// Camera sirf katanaState.cam ko damp-follow karta hai.
// Intro + Anatomy dono timelines isi object ko tween karti hain.
function Rig() {
  const camera = useThree((s) => s.camera)
  const look = useRef(new THREE.Vector3())

  useEffect(() => {
    const onMove = (e) => {
      katanaState.mouse.x = (e.clientX / window.innerWidth) * 2 - 1
      katanaState.mouse.y = -((e.clientY / window.innerHeight) * 2 - 1)
    }
    window.addEventListener('pointermove', onMove)
    return () => window.removeEventListener('pointermove', onMove)
  }, [])

  useFrame((state, delta) => {
    const d = Math.min(delta, 0.05)
    const c = katanaState.cam
    const m = katanaState.mouse
    const px = katanaState.parallax
    camera.position.x = THREE.MathUtils.damp(camera.position.x, c.x + m.x * 7 * px, 3.2, d)
    camera.position.y = THREE.MathUtils.damp(camera.position.y, c.y + m.y * 4 * px, 3.2, d)
    camera.position.z = THREE.MathUtils.damp(camera.position.z, c.z, 3.2, d)
    look.current.set(c.tx, c.ty, c.tz)
    camera.lookAt(look.current)
  })

  // Intro ΓÇö paused; Preloader handover par play hoga
  useEffect(() => {
      if (REDUCED) {
    // Seedha final pose ΓÇö no cinematic draw
    Object.assign(katanaState, { unsheath: 1, sayaLift: 1, baseY: 46 })
    Object.assign(katanaState.cam, CAM_END)
    return
  }
 
    const tl = gsap.timeline({ paused: true })
      // Sword frame ke center mein uthta hai (draw ke saath parallel)
      .to(katanaState, { baseY: 46, duration: 2.6, ease: 'power2.inOut' }, 0.35)
      .to(katanaState, { unsheath: 1, duration: 1.7, ease: 'power3.inOut' }, 0.35)
      .to(katanaState, { wind: 2.4, duration: 0.45, ease: 'power2.out' }, 0.75)
      .to(katanaState, { wind: 0, duration: 2.0, ease: 'power1.in' }, 1.2)
      .to(katanaState, { sayaLift: 1, duration: 1.7, ease: 'power2.in' }, 1.1)
      .to(katanaState.cam, { ...CAM_END, duration: 2.6, ease: 'power2.inOut' }, 0.35)

    katanaAPI.replay = () => tl.play()
    return () => { tl.kill(); katanaAPI.replay = () => {} }
  }, [])

  return null
}

// Hero scroll ΓåÆ katanaState.heroScroll
function HeroScrollLink() {
  useEffect(() => {
    if (!document.querySelector('#hero')) return
    const st = ScrollTrigger.create({
      trigger: '#hero', start: 'top top', end: 'bottom top', scrub: true,
      onUpdate: (self) => { katanaState.heroScroll = self.progress },
    })
    return () => st.kill()
  }, [])
  return null
}

export default function KatanaScene({ active = true }) {
  return (
    <div className="fixed inset-0 z-0" aria-hidden>
      <Canvas
        dpr={[1, 2]}
        frameloop={active ? 'always' : 'never'}
        camera={{ position: [60, 20, 140], fov: 35, near: 0.5, far: 600 }}
        gl={{ antialias: true }}
      >
        <color attach="background" args={['#141210']} />
        <fog attach="fog" args={['#141210', 180, 420]} />

        <ambientLight intensity={0.15} />
        <directionalLight position={[60, 80, 40]} intensity={1.6} color="#fff4e0" />
        <directionalLight position={[-80, 40, -60]} intensity={0.6} color="#7a8ba3" />

        <Suspense fallback={null}>
          <Katana />
          <Petals />
          <Environment preset="city" />
        </Suspense>

        <Rig />
        <HeroScrollLink />
      </Canvas>
    </div>
  )
}

import { useMemo, useRef, useEffect } from 'react'
import * as THREE from 'three'
import { useFrame } from '@react-three/fiber'
import { katanaState } from './katanaState'
import { REDUCED } from '../utils/gsapSetup' 

// Sakura petal shape ΓÇö tip par V-notch (asli sakura identification)
function petalShape() {
  const s = new THREE.Shape()
  s.moveTo(0, -0.55)
  s.bezierCurveTo(0.42, -0.42, 0.5, 0.1, 0.3, 0.45)
  s.lineTo(0, 0.26)
  s.lineTo(-0.3, 0.45)
  s.bezierCurveTo(-0.5, 0.1, -0.42, -0.42, 0, -0.55)
  return s
}

export default function Petals({ count }) {
   if (REDUCED) return null
  const n = count ?? (typeof window !== 'undefined' && window.innerWidth < 768 ? 90 : 240)
  const mesh = useRef(null)
  const windSm = useRef(0)
  const dummy = useMemo(() => new THREE.Object3D(), [])

  // Per-petal data ΓÇö position, phase, speeds (InstancedMesh = 1 draw call)
  const petals = useMemo(
    () => Array.from({ length: n }, () => ({
      x: (Math.random() - 0.5) * 160,
      y: Math.random() * 140 - 60,
      z: (Math.random() - 0.5) * 80 - 15,
      fall: 3.5 + Math.random() * 4.5,
      phase: Math.random() * Math.PI * 2,
      swayFreq: 0.5 + Math.random() * 0.9,
      rx: Math.random() * Math.PI * 2,
      ry: Math.random() * Math.PI * 2,
      rz: Math.random() * Math.PI * 2,
      rsx: (Math.random() - 0.5) * 2.2,
      rsy: (Math.random() - 0.5) * 2.2,
      rsz: (Math.random() - 0.5) * 1.4,
      scale: 0.5 + Math.random() * 0.7,
    })),
    [n]
  )

  useEffect(() => {
    mesh.current?.instanceMatrix?.setUsage(THREE.DynamicDrawUsage)
  }, [])

  useFrame((state, delta) => {
    const dt = Math.min(delta, 0.05) // tab-switch spike guard
    const t = state.clock.elapsedTime
   windSm.current = THREE.MathUtils.damp(
  windSm.current,
  katanaState.wind + (katanaState.windImpulse || 0),
  2.2, dt
)
const wind = windSm.current

    for (let i = 0; i < petals.length; i++) {
      const p = petals[i]
      p.y -= p.fall * dt * (1 + wind * 0.7)
      p.x += (Math.sin(t * p.swayFreq + p.phase) * 0.5 + wind * 2.0) * dt
      p.z += Math.cos(t * p.swayFreq * 0.8 + p.phase) * 0.35 * dt
      const flut = 1 + wind * 2.5
      p.rx += dt * p.rsx * flut
      p.ry += dt * p.rsy * flut
      p.rz += dt * p.rsz * flut

      if (p.y < -70) { p.y = 80; p.x = (Math.random() - 0.5) * 160 }
      if (p.x > 95) p.x = -95
      if (p.x < -95) p.x = 95

      dummy.position.set(p.x, p.y, p.z)
      dummy.rotation.set(p.rx, p.ry, p.rz)
      dummy.scale.setScalar(p.scale)
      dummy.updateMatrix()
      mesh.current.setMatrixAt(i, dummy.matrix)
    }
    mesh.current.instanceMatrix.needsUpdate = true
  })

  return (
    <instancedMesh ref={mesh} args={[null, null, n]} frustumCulled={false}>
